 void pumpImages(){
  if(closing_||!state().active())return;
  if(imageTask_&&imageTask_->result.wait_for(std::chrono::seconds(0))==std::future_status::ready){
   const bool cancelled=imageTask_->cancelled->load();auto found=images_.find(decodingImage_);
   try{auto image=imageTask_->result.get();if(found!=images_.end()&&!cancelled){ImageUpload upload;upload.source=decodingImage_;upload.image=std::move(image);imageUpload_=std::move(upload);}}
   catch(...){if(found!=images_.end()&&!cancelled){found->second.failed=true;imageError_=true;invalidate();}}
   imageTask_.reset();decodingImage_.clear();
  }
  if(imageUpload_){auto& upload=*imageUpload_;auto found=images_.find(upload.source);if(found==images_.end())imageUpload_.reset();else try{
   if(!upload.surface)upload.surface=os::instance()->makeRgbaSurface(upload.image.width,upload.image.height);
   if(!upload.surface)throw std::runtime_error("Image surface unavailable");
   // Upload at most 256K pixels per event-loop pump. Keep partial surfaces private.
   const int count=std::min(upload.image.height-upload.row,std::max(1,262144/upload.image.width));
   uploadRgbaRegion(*upload.surface,upload.image.pixels.data()+std::size_t(upload.row)*upload.image.width,upload.image.width,count,upload.image.width,0,upload.row);upload.row+=count;++imageUploadPumps_;
   if(upload.row==upload.image.height){found->second.width=upload.image.width;found->second.height=upload.image.height;found->second.surface=std::move(upload.surface);imageUpload_.reset();invalidate();}
  }catch(...){found->second.failed=true;imageError_=true;imageUpload_.reset();invalidate();}}
  if(!imageTask_&&!imageUpload_)for(auto& entry:images_)if(!entry.second.surface&&!entry.second.failed){decodingImage_=entry.first;try{imageTask_=startFormImage(entry.first);}catch(...){entry.second.failed=true;imageError_=true;invalidate();}break;}
 }

